package com.aoo.bcg.version;
import org.h2.jdbcx.JdbcDataSource;import org.junit.jupiter.api.*;import java.sql.*;import java.time.*;import static org.junit.jupiter.api.Assertions.*;
final class JdbcVersionRepositoryTest {
 private JdbcDataSource ds;
 @BeforeEach void schema()throws Exception{ds=new JdbcDataSource();ds.setURL("jdbc:h2:mem:version;MODE=MySQL;DB_CLOSE_DELAY=-1");try(Connection c=ds.getConnection();Statement s=c.createStatement()){s.execute("DROP ALL OBJECTS");s.execute("CREATE TABLE aoo_client_release(id BIGINT PRIMARY KEY,platform VARCHAR,channel VARCHAR,version VARCHAR,version_code BIGINT,min_supported_version VARCHAR,force_update BOOLEAN,rollout_percent INT,rollback_version VARCHAR,download_url VARCHAR,state VARCHAR,published_at TIMESTAMP)");s.execute("CREATE TABLE aoo_client_notice(id BIGINT PRIMARY KEY,platform VARCHAR,channel VARCHAR,title VARCHAR,body VARCHAR,severity VARCHAR,starts_at TIMESTAMP,ends_at TIMESTAMP,enabled BOOLEAN)");s.execute("CREATE TABLE aoo_maintenance_window(id BIGINT PRIMARY KEY,platform VARCHAR,channel VARCHAR,starts_at TIMESTAMP,ends_at TIMESTAMP,message VARCHAR,login_blocked BOOLEAN,enabled BOOLEAN)");s.execute("CREATE TABLE aoo_resource_manifest(id BIGINT PRIMARY KEY,release_id BIGINT,version VARCHAR,content_sha256 VARCHAR,signature_algorithm VARCHAR,key_id VARCHAR,signature VARCHAR,state VARCHAR)");s.execute("CREATE TABLE aoo_resource_manifest_entry(manifest_id BIGINT,asset_path VARCHAR,size_bytes BIGINT,sha256 VARCHAR)");s.execute("CREATE TABLE aoo_client_feature_flag(flag_key VARCHAR,platform VARCHAR,channel VARCHAR,enabled BOOLEAN,flag_value VARCHAR,rollout_percent INT,enabled_from TIMESTAMP,enabled_until TIMESTAMP)");s.execute("CREATE TABLE aoo_server_directory(id BIGINT PRIMARY KEY,server_code VARCHAR,display_name VARCHAR,region VARCHAR,public_endpoint VARCHAR,platform VARCHAR,channel VARCHAR,state VARCHAR,weight INT,rollout_percent INT,migrate_to_server_id BIGINT,message VARCHAR,directory_revision BIGINT,visible_from TIMESTAMP,visible_until TIMESTAMP)");s.execute("INSERT INTO aoo_client_release VALUES(1,'android','stable','3.0.0',300,'2.5.0',TRUE,100,'2.9.0','https://cdn/v3','ACTIVE',TIMESTAMP '2026-08-01 00:00:00')");s.execute("INSERT INTO aoo_resource_manifest VALUES(2,1,'3.0.0','"+"a".repeat(64)+"','Ed25519','key-1','sig','PUBLISHED')");s.execute("INSERT INTO aoo_resource_manifest_entry VALUES(2,'bundle.bin',42,'"+"b".repeat(64)+"')");s.execute("INSERT INTO aoo_client_feature_flag VALUES('new_lobby','*','*',TRUE,'v2',100,TIMESTAMP '2026-08-01 00:00:00',NULL)");s.execute("INSERT INTO aoo_server_directory VALUES(11,'cn-1','一区','cn','wss://cn-1','*','*','ACTIVE',100,100,NULL,NULL,9,TIMESTAMP '2026-08-01 00:00:00',NULL)");}}
 @Test void readsEligibleReleaseAndImmutableManifest(){var r=new JdbcVersionRepository(ds);var now=Instant.parse("2026-08-24T00:00:00Z");var release=r.eligibleRelease("android","stable",99,now).orElseThrow();assertEquals("3.0.0",release.version());var m=r.manifest(release.id()).orElseThrow();assertEquals("Ed25519",m.signatureAlgorithm());assertEquals("bundle.bin",m.assets().getFirst().path());assertEquals("new_lobby",r.featureFlags("android","stable",99,now).getFirst().key());assertEquals(11,r.directory("android","stable",99,null,now).selectedServerId());}
}
